#include "stdafx.h"#include "HcdDebugSimpleFrame.h"#include "PrjView.h"#include "ListOfBlocksView.h"#include "Resource.h"#include "HcdDebugDoc.h"#include "FieldsView.h"// KHcdDebugSimpleFrameIMPLEMENT_DYNCREATE(KHcdDebugSimpleFrame, CFrameWnd)KHcdDebugSimpleFrame::KHcdDebugSimpleFrame(): m_pDocument( NULL ){}KHcdDebugSimpleFrame::~KHcdDebugSimpleFrame(){}BEGIN_MESSAGE_MAP(KHcdDebugSimpleFrame, CFrameWnd)  ON_WM_CREATE()  ON_WM_TIMER()END_MESSAGE_MAP()// KHcdDebugSimpleFrame message handlersBOOL KHcdDebugSimpleFrame::OnCreateClient(LPCREATESTRUCT lpcs, CCreateContext* pContext){  if( pContext->m_pCurrentDoc )  {    ASSERT(pContext->m_pCurrentDoc->IsKindOf(RUNTIME_CLASS(KHcdDebugDoc)));    m_pDocument = (KHcdDebugDoc*)pContext->m_pCurrentDoc;  }  BOOL bCreateSpltr = m_wndSplitter.CreateStatic( this, 1, 2);  pContext->m_pCurrentFrame = this;  int cxCur = 350;//ReadSettings();  bCreateSpltr = m_wndSplitter.CreateView( 0, 0, RUNTIME_CLASS(KPrjView), CSize(cxCur, 0), pContext );  bCreateSpltr = m_wndSplitter2.CreateStatic( & m_wndSplitter, 2, 1, WS_CHILD|WS_VISIBLE,  m_wndSplitter.IdFromRowCol(0,1) );  bCreateSpltr = m_wndSplitter2.CreateView( 0, 0, RUNTIME_CLASS(KListOfBlocksView), CSize(600, 400), pContext );  bCreateSpltr = m_wndSplitter2.CreateView( 1, 0, RUNTIME_CLASS(KFieldsView), CSize(600, 0), pContext );  SetTimer( 500, 500, NULL );  return bCreateSpltr;}static UINT indicators[] ={  ID_SEPARATOR,  ID_SEPARATOR,};int KHcdDebugSimpleFrame::OnCreate(LPCREATESTRUCT lpCreateStruct){  if (CFrameWnd::OnCreate(lpCreateStruct) == -1)    return -1;  if (!m_wndStatusBar.Create(this) ||  !m_wndStatusBar.SetIndicators(indicators, _countof(indicators) ))  {    TRACE0("Failed to create status bar\n");    return -2;      // fail to create  }  m_wndStatusBar.SetPaneInfo( 0, 251 , SBPS_NORMAL |SBPS_STRETCH, 25);  m_wndStatusBar.SetPaneInfo( 1, 252 , SBPS_NORMAL |SBPS_STRETCH, 200);  SetTimer( 500, 500, NULL );  return 0;}void KHcdDebugSimpleFrame::OnTimer(UINT_PTR nIDEvent){  if( 500==nIDEvent )  {    if( !m_pDocument || !m_pDocument->m_pParams )    {      KillTimer( nIDEvent );      return;    }    char szBuf[256] = {};    sprintf_s( szBuf, "Шаг-%d, dtS=%f", m_pDocument->m_pParams->nStep, m_pDocument->m_pParams->dtS );    m_wndStatusBar.SetPaneText( 0, szBuf );  }  CFrameWnd::OnTimer(nIDEvent);}